create schema if not exists private; revoke all on schema private from public, anon, authenticated; grant usage on schema private to service_role; create table if not exists private.apex_gateway_transactions (id uuid primary key default gen_random_uuid(), reference_kind text not null check (reference_kind in ('order','wallet_topup')), reference_id bigint not null, user_id uuid not null, provider_key text not null, provider_session_id text, provider_payment_id text, amount_sar numeric(12,2) not null check (amount_sar > 0), currency text not null default 'SAR' check (currency='SAR'), status text not null default 'pending' check (status in ('pending','paid','failed','cancelled','refunded')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), paid_at timestamptz); create unique index if not exists apex_gateway_provider_payment_uidx on private.apex_gateway_transactions(provider_key,provider_payment_id) where provider_payment_id is not null; create unique index if not exists apex_gateway_reference_provider_uidx on private.apex_gateway_transactions(reference_kind,reference_id,provider_key); create table if not exists private.apex_payment_webhook_events (id bigint generated always as identity primary key, provider_key text not null, event_id text not null, event_type text, payload_sha256 text not null, transaction_id uuid references private.apex_gateway_transactions(id), processing_status text not null default 'received' check (processing_status in ('received','processed','ignored','failed')), received_at timestamptz not null default now(), processed_at timestamptz, error_code text, unique(provider_key,event_id)); create table if not exists private.apex_shipping_jobs (id uuid primary key default gen_random_uuid(), order_id bigint not null unique references public.apex_orders(id) on delete restrict, carrier_code text not null, external_shipment_id text, tracking_number text, status text not null default 'pending' check (status in ('pending','created','in_transit','delivered','failed','cancelled')), request_id uuid not null default gen_random_uuid(), response_sha256 text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); revoke all on all tables in schema private from public, anon, authenticated; grant select,insert,update,delete on all tables in schema private to service_role; grant usage,select on all sequences in schema private to service_role;